  /* Write unit */
  dma_write_unit dma_write_unit_i (
      .clk_i(clk_cg),
      .rst_ni,

      .reg2hw_i(reg2hw),

      .dma_start_i(dma_start),
      .wait_for_tx_i(wait_for_tx),
      .enable_wait_for_tx_i(enable_wait_for_tx),
      .slot_wait_counter_i(reg2hw.slot_wait_counter.q),

