    hw2reg.status.ready.d = (dma_state_q == DMA_READY);
    hw2reg.status.window_done.d = window_event;
    hw2reg.window_count.d = window_counter[7:0];
  end


  assign circular_mode = reg2hw.mode.q == 1;
